WITH ranked AS (SELECT id, order_id, product_id, quantity FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY product_id ORDER BY quantity DESC NULLS LAST, id) AS rn FROM order_items) ranked WHERE rn = 1), scored AS (SELECT *, MIN(quantity) OVER (PARTITION BY order_id ORDER BY quantity, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS last3_min_quantity, SUM(quantity) OVER (PARTITION BY order_id ORDER BY quantity, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS last3_sum_quantity, AVG(quantity) OVER (PARTITION BY order_id ORDER BY quantity, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS last3_avg_quantity, MAX(quantity) OVER (PARTITION BY order_id ORDER BY quantity, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS last3_max_quantity, LAG(quantity, 1, 0) OVER (ORDER BY quantity, id) AS prev_quantity FROM ranked), metrics AS (SELECT id, prev_quantity, COUNT(last3_min_quantity) OVER w_recent AS running_count_last3_min_quantity, AVG(last3_min_quantity) OVER w_recent AS running_avg_last3_min_quantity, SUM(last3_min_quantity) OVER w_recent AS running_sum_last3_min_quantity FROM scored WHERE last3_max_quantity <= 6.2 WINDOW w_recent AS (PARTITION BY order_id ORDER BY last3_sum_quantity, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)), cleaned AS (SELECT id, running_avg_last3_min_quantity, CAST(running_sum_last3_min_quantity AS INT) AS running_sum_last3_min_quantity_int, ROUND(prev_quantity * 100, 2) AS adjusted_prev_quantity FROM metrics WHERE prev_quantity <= 8) SELECT *, AVG(running_sum_last3_min_quantity_int) OVER w_grp AS running_avg_running_sum_last3_min_quantity_int, SUM(running_sum_last3_min_quantity_int) OVER w_grp AS running_sum_running_sum_last3_min_quantity_int, MIN(running_sum_last3_min_quantity_int) OVER w_grp AS running_min_running_sum_last3_min_quantity_int FROM cleaned WINDOW w_grp AS (ORDER BY adjusted_prev_quantity, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
